-- Content review: clarify failure boundaries; keep all prior versions intact.
UPDATE question_bank SET reference_answer=CONCAT(reference_answer, '若业务对象必须修改订单号，应以独立且不可变的内部 ID 作为键；涉及迁移旧键时在受控流程中移除旧映射再插入新映射，不能假定修改对象会自动更新映射。'),version=version+1 WHERE id='qb-java-001';
UPDATE question_bank SET reference_answer=CONCAT(reference_answer, '分页还需固定时间字段和 ID 的方向，处理 created_at 相同的记录。若使用 DESC 排序，核对索引扫描方向与执行计划，不把开发环境的小表计划等同于生产效果。'),version=version+1 WHERE id='qb-database-001';
UPDATE question_bank SET reference_answer=CONCAT(reference_answer, '并发回填可能在更新失效后写回旧值，因此 TTL 本身不严格保证从数据库提交起计的一分钟上限。若这是一条硬性时效承诺，需增加版本约束、读路径校验或绕过缓存，并测量完整时间线。'),version=version+1 WHERE id='qb-redis-001';
UPDATE question_bank SET reference_answer=CONCAT(reference_answer, 'AtomicLong 仍有数值溢出和进程重启边界；用于持久业务序号时还要处理跨实例唯一性，不能将进程内原子计数当成全局 ID 服务。'),version=version+1 WHERE id='qb-concurrency-001';
UPDATE question_bank SET reference_answer=CONCAT(reference_answer, '分位数应基于原始分布或可合并的直方图计算，不能把多个实例各自的 p99 简单平均。关联采样率、窗口和分桶精度后再比较不同环境的结果。'),version=version+1 WHERE id='qb-performance-001';
UPDATE question_bank SET reference_answer=CONCAT(reference_answer, '重试总预算还需包含退避等待，避免重试持续到调用方已放弃之后；取消信号应尽可能传播，并验证客户端超时后的服务端资源是否最终释放。'),version=version+1 WHERE id='qb-reliability-001';
INSERT INTO question_bank (id,title,question,topic,competency_id,difficulty,tags_json,key_points_json,reference_answer,common_mistakes_json,follow_ups_json,source_type) VALUES ('qb-java-006','虚拟线程与外部资源上限','将阻塞 HTTP 接口从固定线程池改为 Java 21 虚拟线程后，数据库连接等待骤增。虚拟线程解决了什么，又没有解决什么？如何验证改造收益？','JAVA','foundation','ADVANCED',JSON_ARRAY('Java 21','虚拟线程','资源预算'),JSON_ARRAY('线程成本与外部容量区分','有界并发与超时','同负载验证'),'虚拟线程降低大量阻塞任务占用平台线程的成本，但不增加数据库连接数、下游容量或 CPU 算力。为数据库和外部调用分别设置并发预算、连接与请求超时，过载时排队有界或快速拒绝，不把每个请求都立即放行。还需观察 Java 21 中持有监视器时阻塞等可能钉住载体线程的情形，基于实际调用栈判断。对比相同到达率下的吞吐、尾延迟、连接等待、CPU 与内存，验证故障和取消后的资源释放。',JSON_ARRAY('虚拟线程越多数据库吞吐越高','改用虚拟线程后不再需要背压'),JSON_ARRAY('如何为不同租户分配数据库并发预算？','CPU 密集任务是否适合直接无限增加虚拟线程？'),'ORIGINAL');
INSERT INTO question_bank (id,title,question,topic,competency_id,difficulty,tags_json,key_points_json,reference_answer,common_mistakes_json,follow_ups_json,source_type) VALUES ('qb-database-006','读写分离后的读己之写','用户更新资料后立即读取，偶尔看到旧值。读请求走异步复制的只读节点。如何提供读己之写，同时保留大部分读扩展能力？','DATABASE','storage','ADVANCED',JSON_ARRAY('MySQL','复制延迟','读写分离'),JSON_ARRAY('异步复制可见性','会话一致性策略','超时和故障边界'),'先确认读路径与复制应用进度，区分缓存陈旧和副本延迟。更新后的关键读取可在有限时间窗口路由主库，或携带提交位置并等待副本应用到该位置后再读；等待必须受请求预算限制，超时可回主库或给出明确的稍后刷新提示。路由策略要考虑主库故障、连接切换和多设备访问，而非只用固定睡眠掩盖延迟。用故意暂停复制和恢复的实验验证可见性、主库额外负载及降级行为。',JSON_ARRAY('异步副本读取总能看到刚提交的数据','固定睡眠几百毫秒能保证所有场景一致'),JSON_ARRAY('跨设备登录后怎样传递一致性要求？','复制延迟长期扩大时如何防止回主库压垮写入？'),'ORIGINAL');
INSERT INTO question_bank (id,title,question,topic,competency_id,difficulty,tags_json,key_points_json,reference_answer,common_mistakes_json,follow_ups_json,source_type) VALUES ('qb-redis-006','多级缓存的版本失序','两个应用实例各有本地缓存，Redis 更新后通过消息通知失效。通知可能丢失或乱序，如何限制旧值存活并防止旧通知覆盖新值？','REDIS','storage','ADVANCED',JSON_ARRAY('Redis','本地缓存','版本控制'),JSON_ARRAY('消息可靠性与重放','单调版本比较','有界陈旧与回源保护'),'为记录携带权威存储产生的单调版本，本地缓存保留值和版本；收到通知时只按约定处理更高版本，不能让迟到旧值覆盖新值。通知失效仅是加速收敛机制，仍设置容量和 TTL，并监测消费进度及丢失后的重建路径。严格读取可绕过本地层，允许陈旧的读取需给出可测量窗口。演练通知丢失、乱序、实例离线再加入和批量失效，验证版本规则及数据库回源上限。',JSON_ARRAY('使用发布订阅就不会丢失失效通知','只加版本号而不定义比较规则就能保证一致'),JSON_ARRAY('删除后重建同一 ID 应如何保持版本单调？','本地缓存和 Redis 同时过期时怎样避免回源风暴？'),'ORIGINAL');
INSERT INTO question_bank (id,title,question,topic,competency_id,difficulty,tags_json,key_points_json,reference_answer,common_mistakes_json,follow_ups_json,source_type) VALUES ('qb-concurrency-006','公平与吞吐的租户隔离','一个大租户占满任务线程，其他租户的短任务排队数分钟。如何设计调度，使资源有界且避免小租户长期饥饿？','CONCURRENCY','concurrency','ADVANCED',JSON_ARRAY('并发控制','公平调度','多租户'),JSON_ARRAY('全局和租户双重预算','调度公平性','取消与资源归还'),'同时限制全局并发、单租户在途任务和排队数量，再按租户轮转或加权公平调度，给小租户保留最小服务机会。长任务可划分可中断批次，无法切分时使用独立池或配额，不能仅靠公平锁解决整个队列的问题。超时、取消和异常路径都必须归还配额，防止许可泄漏。以不同任务时长、租户权重和持续过载压测，记录各租户等待分位数、拒绝率与全局利用率，明确公平带来的吞吐代价。',JSON_ARRAY('全局 FIFO 自动保证租户公平','把所有任务放进公平锁就能避免饥饿'),JSON_ARRAY('权重动态变化时如何处理已有排队任务？','单个任务无法取消时怎样保护整体资源？'),'ORIGINAL');
INSERT INTO question_bank (id,title,question,topic,competency_id,difficulty,tags_json,key_points_json,reference_answer,common_mistakes_json,follow_ups_json,source_type) VALUES ('qb-performance-006','批处理优化的尾延迟代价','日志写入改为每 100 条或每秒批量提交后吞吐上升，但低流量用户反馈延迟变差。如何设计批次、计时器和验证指标？','PERFORMANCE','performance','ADVANCED',JSON_ARRAY('性能','批处理','尾延迟'),JSON_ARRAY('吞吐与等待时间取舍','大小和时间双触发','失败恢复与观测'),'批量提交减少每条固定开销，却引入等待凑批时间。设置最大条数、最大字节数及从首条进入起算的最大等待时间，由任一阈值触发，并限制待提交队列。低流量时计时器必须真正唤醒刷写；异常时处理批次重试与幂等，停机时在预算内排空或持久化剩余任务。分别测高低流量、变长消息和故障恢复，比较端到端延迟分位数、批次大小、吞吐及内存，而不只看单次批次提交耗时。',JSON_ARRAY('批量越大在所有负载下都越好','计时器到期即代表持久化已经完成'),JSON_ARRAY('如何避免重试导致批次内重复写入？','消息大小差异很大时为何需要字节阈值？'),'ORIGINAL');
INSERT INTO question_bank (id,title,question,topic,competency_id,difficulty,tags_json,key_points_json,reference_answer,common_mistakes_json,follow_ups_json,source_type) VALUES ('qb-reliability-006','备份存在但恢复不可用','数据库备份任务每天显示成功，但灾难演练时发现无法在目标时间内恢复。如何建立可验证的备份恢复流程？','RELIABILITY','reliability','ADVANCED',JSON_ARRAY('可靠性','备份恢复','演练'),JSON_ARRAY('备份完整性与可恢复性','增量链与恢复点','隔离恢复和业务核验'),'任务成功只说明备份过程返回成功，需在隔离环境定期恢复并核验完整性、事务一致性和关键业务约束。记录全量备份、增量链或日志的依赖、加密密钥与版本兼容要求，保护恢复凭据并演练它们可用。测量下载、解密、导入、日志重放、校验及切流总耗时，核对实际恢复点与目标 RPO/RTO。恢复环境禁止向真实用户发送通知或触发支付，演练完成清理测试副本并保留验证报告。',JSON_ARRAY('备份文件存在就说明可恢复','恢复成功只需确认数据库进程能启动'),JSON_ARRAY('怎样验证备份期间发生的业务写入仍保持一致？','密钥丢失或备份链中间缺失时有哪些恢复选择？'),'ORIGINAL');

INSERT INTO question_bank_versions (question_id,version,content_json,change_note)
SELECT id,version,JSON_OBJECT(
'id',id,'version',version,'title',title,'question',question,'topic',topic,'competencyId',competency_id,
'difficulty',difficulty,'tags',tags_json,'keyPoints',key_points_json,'referenceAnswer',reference_answer,
'commonMistakes',common_mistakes_json,'followUps',follow_ups_json,
'sourceType',source_type,'sourceTitle',source_title,'sourceUrl',source_url),'补充边界条件并新增六道原创场景题' FROM question_bank q WHERE NOT EXISTS (SELECT 1 FROM question_bank_versions v WHERE v.question_id=q.id AND v.version=q.version);

